from lxml import etree
from os import path


class SiteConfig(object):
    def get_radios_exist_value(self, filepath, radios):
        """
        When radio is in active state, method return True if not return False
        """
        xml_tree = self._get_ast(filepath)
        radio_objects = self._get_all_radio_objects(xml_tree, radios)
        radio_exist_value = self._get_all_exists(radio_objects)
        return radio_exist_value

    @staticmethod
    def _get_ast(filepath):
        if not path.exists(filepath):
            raise IOError("File {} not exists".format(filepath))

        root = etree.parse(filepath)
        return root.iter()

    @staticmethod
    def _get_all_radio_objects(xml_tree, radios):
        elements = []
        for radio in radios:
            for element in xml_tree:
                if element.tag == '_unitName' and element.text == radio:
                    elements.append(element)
        return elements

    @staticmethod
    def _get_all_exists(radio_objects):
        exists_value = []
        for element in radio_objects:
            for grandelement in element.getparent().iter():
                if grandelement.tag == '_exist':
                    exists_value.append(int(grandelement.text))
        return exists_value
